function makeStudioBlock(kind) {
    const id = makeStudioId("blk");
    if (kind === "hero") return {
        id,
        type: "hero",
        eyebrow: studioText("NEW PAGE", "HALAMAN BARU"),
        heading: studioText("A new chapter", "Bab baru"),
        body: studioText("Add an introduction for this page.", "Tambahkan pengantar untuk halaman ini.")
    };
    if (kind === "text") return {
        id,
        type: "text",
        heading: studioText("Section heading", "Judul bagian"),
        body: studioText("Write your content here.", "Tulis konten di sini.")
    };
    if (kind === "image") return {
        id,
        type: "image",
        image: null,
        alt: studioText("", ""),
        caption: studioText("", "")
    };
    if (kind === "cards") return {
        id,
        type: "cards",
        heading: studioText("Highlights", "Sorotan"),
        items: [
            {
                id: makeStudioId("item"),
                title: studioText("New card", "Kartu baru"),
                body: studioText("Describe this item.", "Jelaskan item ini."),
                tag: "FEATURE"
            }
        ]
    };
    if (kind === "stats") return {
        id,
        type: "stats",
        heading: studioText("At a glance", "Sekilas"),
        items: [
            {
                id: makeStudioId("item"),
                value: "03",
                label: studioText("Highlights", "Sorotan")
            }
        ]
    };
    if (kind === "timeline") return {
        id,
        type: "timeline",
        heading: studioText("Timeline", "Linimasa"),
        items: [
            {
                id: makeStudioId("item"),
                period: "2026",
                title: studioText("Milestone", "Pencapaian"),
                body: studioText("Describe this milestone.", "Jelaskan pencapaian ini.")
            }
        ]
    };
    if (kind === "gallery") return {
        id,
        type: "gallery",
        heading: studioText("Gallery", "Galeri"),
        images: []
    };
    if (kind === "cta") return {
        id,
        type: "cta",
        heading: studioText("Let's connect", "Mari terhubung"),
        body: studioText("Add a short call to action.", "Tambahkan ajakan singkat."),
        buttonLabel: studioText("Contact me", "Hubungi saya"),
        href: "/#contact"
    };
    return {
        id,
        type: "divider"
    };
}
/** Builds a new custom homepage section placed after every existing section. Shared by Studio and Sections & order. */ function newCustomSection(draft, title, kind, fromTemplate) {
    const clean = title.trim() || "New page";
    const basePalette = draft.appearance.preset === "custom" ? {
        accent: draft.appearance.accentColor,
        secondary: draft.appearance.secondaryColor
    } : palettes[draft.appearance.preset];
    const orders = [
        ...draft.sections.filter((item)=>item.id !== "header" && item.id !== "footer").map((item)=>item.order),
        ...draft.customPages.pages.map((item)=>item.order)
    ];
    return {
        id: makeStudioId("section"),
        slug: uniqueStudioSlug(clean, new Set(draft.customPages.pages.map((item)=>item.slug))),
        title: studioText(clean, clean),
        summary: studioText("", ""),
        visible: true,
        showInNav: true,
        order: Math.min(98, Math.max(0, ...orders) + 1),
        accentColor: fromTemplate?.accentColor || basePalette.accent,
        secondaryColor: fromTemplate?.secondaryColor || basePalette.secondary,
        blocks: structuredClone(fromTemplate?.blocks || starterBlocks(kind))
    };
}
function starterBlocks(kind) {
    if (kind === "blank") return [];
    if (kind === "portfolio") return [
        makeStudioBlock("hero"),
        makeStudioBlock("cards"),
        makeStudioBlock("stats"),
        makeStudioBlock("cta")
    ];
    if (kind === "article") return [
        makeStudioBlock("hero"),
        makeStudioBlock("text"),
        makeStudioBlock("text"),
        makeStudioBlock("image"),
        makeStudioBlock("cta")
    ];
    if (kind === "research") return [
        makeStudioBlock("hero"),
        makeStudioBlock("stats"),
        makeStudioBlock("timeline"),
        makeStudioBlock("text")
    ];
    return [
        makeStudioBlock("hero"),
        makeStudioBlock("gallery"),
        makeStudioBlock("text")
    ];
}
